from ortools.sat.python import cp_model
import itertools
import json

def main():
    projects = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J']

    conceptual_duration = {p: 1 for p in projects}

    compliance_duration = {
        'A': 34, 'B': 7, 'C': 21, 'D': 25, 'E': 32,
        'F': 13, 'G': 12, 'H': 14, 'I': 29, 'J': 15
    }

    final_duration = {
        'A': 58, 'B': 51, 'C': 21, 'D': 26, 'E': 30,
        'F': 21, 'G': 56, 'H': 60, 'I': 48, 'J': 34
    }

    model = cp_model.CpModel()

    horizon = sum(compliance_duration.values()) + sum(final_duration.values()) + len(projects)

    start_conceptual = {}
    start_compliance = {}
    start_final = {}
    partner = {}
    makespan = model.NewIntVar(0, horizon, 'makespan')

    for p in projects:
        start_conceptual[p] = model.NewIntVar(0, horizon, f'start_conceptual_{p}')
        start_compliance[p] = model.NewIntVar(0, horizon, f'start_compliance_{p}')
        start_final[p] = model.NewIntVar(0, horizon, f'start_final_{p}')

        partner[p] = model.NewIntVar(1, 2, f'partner_{p}')

    partner_is_1 = {}
    partner_is_2 = {}
    for p in projects:
        partner_is_1[p] = model.NewBoolVar(f'partner_{p}_is_1')
        partner_is_2[p] = model.NewBoolVar(f'partner_{p}_is_2')
        model.Add(partner[p] == 1).OnlyEnforceIf(partner_is_1[p])
        model.Add(partner[p] == 2).OnlyEnforceIf(partner_is_2[p])
        model.Add(partner_is_1[p] + partner_is_2[p] == 1)

    seq_compliance = {}
    for p in projects:
        for q in projects:
            if p != q:
                seq_compliance[(p, q)] = model.NewBoolVar(f'seq_{p}_{q}')

    for p in projects:
        model.Add(start_conceptual[p] + conceptual_duration[p] <= start_compliance[p])
        model.Add(start_compliance[p] + compliance_duration[p] <= start_final[p])

    for p in projects:
        for q in projects:
            if p != q:
                model.Add(
                    start_compliance[p] + compliance_duration[p] <= start_compliance[q]
                ).OnlyEnforceIf(seq_compliance[(p, q)])

                model.Add(seq_compliance[(p, q)] + seq_compliance[(q, p)] == 1)

    for p in projects:
        for q in projects:
            if p < q:
                both_partner_1 = model.NewBoolVar(f'both_partner_1_{p}_{q}')
                model.AddBoolAnd([partner_is_1[p], partner_is_1[q]]).OnlyEnforceIf(both_partner_1)
                model.AddBoolOr([partner_is_1[p].Not(), partner_is_1[q].Not()]).OnlyEnforceIf(both_partner_1.Not())

                p_before_q_conceptual_1 = model.NewBoolVar(f'p_before_q_conceptual_1_{p}_{q}')

                model.Add(
                    start_conceptual[p] + conceptual_duration[p] <= start_conceptual[q]
                ).OnlyEnforceIf([p_before_q_conceptual_1, both_partner_1])

                model.Add(
                    start_conceptual[q] + conceptual_duration[q] <= start_conceptual[p]
                ).OnlyEnforceIf([p_before_q_conceptual_1.Not(), both_partner_1])

                both_partner_2 = model.NewBoolVar(f'both_partner_2_{p}_{q}')
                model.AddBoolAnd([partner_is_2[p], partner_is_2[q]]).OnlyEnforceIf(both_partner_2)
                model.AddBoolOr([partner_is_2[p].Not(), partner_is_2[q].Not()]).OnlyEnforceIf(both_partner_2.Not())

                p_before_q_conceptual_2 = model.NewBoolVar(f'p_before_q_conceptual_2_{p}_{q}')

                model.Add(
                    start_conceptual[p] + conceptual_duration[p] <= start_conceptual[q]
                ).OnlyEnforceIf([p_before_q_conceptual_2, both_partner_2])

                model.Add(
                    start_conceptual[q] + conceptual_duration[q] <= start_conceptual[p]
                ).OnlyEnforceIf([p_before_q_conceptual_2.Not(), both_partner_2])

    for p in projects:
        for q in projects:
            if p < q:
                both_partner_1_final = model.NewBoolVar(f'both_partner_1_final_{p}_{q}')
                model.AddBoolAnd([partner_is_1[p], partner_is_1[q]]).OnlyEnforceIf(both_partner_1_final)
                model.AddBoolOr([partner_is_1[p].Not(), partner_is_1[q].Not()]).OnlyEnforceIf(both_partner_1_final.Not())

                p_before_q_final_1 = model.NewBoolVar(f'p_before_q_final_1_{p}_{q}')

                model.Add(
                    start_final[p] + final_duration[p] <= start_final[q]
                ).OnlyEnforceIf([p_before_q_final_1, both_partner_1_final])

                model.Add(
                    start_final[q] + final_duration[q] <= start_final[p]
                ).OnlyEnforceIf([p_before_q_final_1.Not(), both_partner_1_final])

                both_partner_2_final = model.NewBoolVar(f'both_partner_2_final_{p}_{q}')
                model.AddBoolAnd([partner_is_2[p], partner_is_2[q]]).OnlyEnforceIf(both_partner_2_final)
                model.AddBoolOr([partner_is_2[p].Not(), partner_is_2[q].Not()]).OnlyEnforceIf(both_partner_2_final.Not())

                p_before_q_final_2 = model.NewBoolVar(f'p_before_q_final_2_{p}_{q}')

                model.Add(
                    start_final[p] + final_duration[p] <= start_final[q]
                ).OnlyEnforceIf([p_before_q_final_2, both_partner_2_final])

                model.Add(
                    start_final[q] + final_duration[q] <= start_final[p]
                ).OnlyEnforceIf([p_before_q_final_2.Not(), both_partner_2_final])

    for p in projects:
        model.Add(start_final[p] + final_duration[p] <= makespan)

    model.Minimize(makespan)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        compliance_times = []
        for p in projects:
            compliance_times.append((p, solver.Value(start_compliance[p])))

        compliance_times.sort(key=lambda x: x[1])
        compliance_sequence = [p for p, _ in compliance_times]

        project_to_index = {project: idx + 1 for idx, project in enumerate(projects)}
        compliance_sequence_indices = [project_to_index[p] for p in compliance_sequence]

        total_design_time = solver.Value(makespan)

        print(json.dumps({
            "compliance_sequence": compliance_sequence_indices,
            "total_design_time": total_design_time
        }))

    else:
        print(json.dumps({
            "compliance_sequence": [],
            "total_design_time": -1
        }))

if __name__ == '__main__':
    main()
